class TestProcessData:
    """测试process_data函数"""

    def test_process_data_normal(self):
        """正常用例：处理包含多个键值对的字典"""
        data = {"name": "john", "city": "beijing", "age": "25"}
        result = process_data(data)
        assert result == {"name": "JOHN", "city": "BEIJING", "age": "25"}

    def test_process_data_single_key(self):
        """边界用例：单个键值对"""
        data = {"key": "value"}
        result = process_data(data)
        assert result == {"key": "VALUE"}

    def test_process_data_empty_dict(self):
        """边界用例：空字典"""
        data = {}
        result = process_data(data)
        assert result == {}

    def test_process_data_mixed_case(self):
        """正常用例：混合大小写"""
        data = {"a": "Hello", "b": "WORLD", "c": "PyThOn"}
        result = process_data(data)
        assert result == {"a": "HELLO", "b": "WORLD", "c": "PYTHON"}

    def test_process_data_numeric_values(self):
        """正常用例：数字值（会被转换为字符串）"""
        data = {"int": 123, "float": 45.67, "zero": 0}
        result = process_data(data)
        assert result == {"int": "123", "float": "45.67", "zero": "0"}

    def test_process_data_already_upper(self):
        """正常用例：已经是大写的值"""
        data = {"key": "ALREADY UPPER"}
        result = process_data(data)
        assert result == {"key": "ALREADY UPPER"}


class TestValidateInput:
    """测试validate_input函数"""

    def test_validate_input_valid(self):
        """正常用例：有效输入"""
        assert validate_input("hello") is True
        assert validate_input("a") is True
        assert validate_input("test string with spaces") is True

    def test_validate_input_empty_string(self):
        """边界用例：空字符串"""
        assert validate_input("") is False

    def test_validate_input_special_chars(self):
        """正常用例：特殊字符"""
        assert validate_input("!@#$%^&*()") is True
        assert validate_input("   ") is True  # 空格不是空字符串
        assert validate_input("123\n456") is True

    def test_validate_input_unicode(self):
        """正常用例：Unicode字符"""
        assert validate_input("你好世界") is True
        assert validate_input("🎉🎊") is True


