class TestDataHandlerIntegration:
    """集成测试"""

    def test_full_workflow(self, caplog):
        """正常用例：完整工作流程"""
        with caplog.at_level(logging.DEBUG):
            # 初始化
            handler = DataHandler("integration_source")
            assert handler.source == "integration_source"
            assert handler.data == {}

            # 处理数据
            test_data = {"name": "test", "value": "123"}
            processed = process_data(test_data)
            assert processed == {"name": "TEST", "value": "123"}

            # 加载数据
            result = handler.load()
            assert result is True

    def test_validate_before_process(self):
        """正常用例：验证后再处理"""
        valid_input = "valid_input_for_processing"
        assert validate_input(valid_input) is True
        assert validate_input_wrapper(valid_input) is True

        # 验证通过后再处理数据
        data = {"input": valid_input}
        result = process_data(data)
        assert result == {"input": valid_input.upper()}


class TestEdgeCases:
    """额外的边界测试"""

    def test_process_data_none_values(self):
        """边界用例：包含None值的字典"""
        data = {"key": None}
        result = process_data(data)
        assert result == {"key": "NONE"}

    def test_process_data_boolean_values(self):
        """边界用例：布尔值"""
        data = {"flag1": True, "flag2": False}
        result = process_data(data)
        assert result == {"flag1": "TRUE", "flag2": "FALSE"}

    def test_process_data_list_values(self):
        """边界用例：列表值（会被转换为字符串）"""
        data = {"items": [1, 2, 3]}
        result = process_data(data)
        assert result == {"items": "[1, 2, 3]"}

    def test_validate_input_with_whitespace_only(self):
        """边界用例：只有空白字符"""
        # 注意：空白字符不是空字符串，长度>0
        assert validate_input("   ") is True
        assert validate_input("\t") is True
        assert validate_input("\n") is True

    def test_data_handler_multiple_instances(self):
        """正常用例：多个实例独立"""
        handler1 = DataHandler("source1")
        handler2 = DataHandler("source2")

        handler1.data = {"key": "value1"}
        handler2.data = {"key": "value2"}

        assert handler1.data != handler2.data
        assert handler1.source == "source1"
        assert handler2.source == "source2"

